def main_solution(operations):
    result = {}
    for operation in operations:
        action = operation[0]
        key = operation[1]
        value = operation[2]
        if action == 'add':
            result[key] = value
        elif action == 'delete':
            result[key] = None
        elif action == 'modify':
            result[key] = value
    return result

